import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { buildSubdivPlan, evaluateSubdiv } from './catmullClark';
import { buildTopologyRaw } from '../mesh/topology';

interface Case {
  name: string;
  levels: number;
  limit: boolean;
  input: { positions: number[]; faces: number[][] };
  nv: number;
  nf: number;
  positions: number[];
}

// Generated by blender/make_subdiv_fixtures.py inside Blender.
const fixtures: { blender: string; cases: Case[] } = JSON.parse(
  readFileSync(new URL('./fixtures/blender-subdiv.json', import.meta.url), 'utf8'),
);

/** Largest distance from any point in `a` to its nearest point in `b`. */
function maxNearest(a: ArrayLike<number>, b: ArrayLike<number>): number {
  let worst = 0;
  for (let i = 0; i < a.length; i += 3) {
    let best = Infinity;
    for (let j = 0; j < b.length; j += 3) {
      const d = (a[i] - b[j]) ** 2 + (a[i + 1] - b[j + 1]) ** 2 + (a[i + 2] - b[j + 2]) ** 2;
      if (d < best) best = d;
    }
    worst = Math.max(worst, Math.sqrt(best));
  }
  return worst;
}

describe(`Catmull-Clark vs Blender ${fixtures.blender}`, () => {
  for (const c of fixtures.cases) {
    it(`${c.name} level ${c.levels} limit=${c.limit}`, () => {
      const nV = c.input.positions.length / 3;
      const plan = buildSubdivPlan(nV, c.input.faces, [], { levels: c.levels, useLimitSurface: c.limit });
      expect(plan.nFinal).toBe(c.nv);
      expect(plan.faces.length).toBe(c.nf);
      const out = new Float64Array(plan.nFinal * 3);
      evaluateSubdiv(plan, c.input.positions, out);
      // Blender approximates the limit at smooth single-face corners (adaptive patches, quality 3);
      // our exact B-spline corner limit differs there by ~0.4% of the edge length. Everything else
      // matches to 1e-4.
      const tol = c.limit && c.name === 'grid2x2' ? 5e-3 : 1e-4;
      expect(maxNearest(c.positions, out)).toBeLessThan(tol);
      expect(maxNearest(out, c.positions)).toBeLessThan(tol);
    });
  }

  it('produces valid all-quad topology at every level', () => {
    const c = fixtures.cases.find((x) => x.name === 'cylinder8')!;
    for (const levels of [1, 2, 3]) {
      const plan = buildSubdivPlan(16, c.input.faces, [], { levels, useLimitSurface: true });
      expect(buildTopologyRaw(plan.nFinal, plan.faces, []).errors).toEqual([]);
      expect(plan.faces.every((f) => f.length === 4)).toBe(true);
    }
  });

  it('re-evaluates without rebuilding (the drag path)', () => {
    const c = fixtures.cases.find((x) => x.name === 'cube' && x.levels === 2 && x.limit)!;
    const plan = buildSubdivPlan(8, c.input.faces, [], { levels: 2, useLimitSurface: true });
    const out = new Float32Array(plan.nFinal * 3);
    const moved = c.input.positions.slice();
    evaluateSubdiv(plan, moved, out);
    const before = out[0];
    moved[0] -= 1; // drag cage vertex 0 outwards along -X
    evaluateSubdiv(plan, moved, out);
    expect(out[0]).toBeLessThan(before);
  });

  it('subdivides loose edges as smooth curves', () => {
    const plan = buildSubdivPlan(3, [], [[0, 1], [1, 2]], { levels: 1, useLimitSurface: false });
    expect(plan.nFinal).toBe(5);
    expect(plan.looseEdges.length).toBe(4);
    const out = new Float64Array(15);
    evaluateSubdiv(plan, [0, 0, 0, 1, 1, 0, 2, 0, 0], out);
    expect(out[4]).toBeCloseTo(0.75); // middle vertex pulled towards the chord (3/4·1 + 1/8·0 + 1/8·0)
    expect(out[0]).toBe(0); // dangling ends stay put
  });
});
